def codex_title_query_render_profile_report_is_valid(
    report: object,
    harness_status: object = None,
    report_path: Path | None = None,
    epoch_status: object = None,
) -> bool:
    """Validate the signed bounded query/render profile without crediting a scenario answer."""
    if not isinstance(report, dict):
        return False
    path = report_path or (LIVE_PROBE_DIR / Path(CODEX_TITLE_QUERY_RENDER_REPORT_RELATIVE_PATH).name)
    try:
        relative_path = path.resolve().relative_to(ROOT.resolve()).as_posix()
        report_bytes = path.read_bytes()
    except (OSError, ValueError):
        return False
    report_sha256 = hashlib.sha256(report_bytes).hexdigest()
    pr_number = report.get('prNumber')
    if (
        relative_path != CODEX_TITLE_QUERY_RENDER_REPORT_RELATIVE_PATH
        or len(report_bytes) > 64 * 1024
        or report.get('evidenceKind') != CODEX_TITLE_QUERY_RENDER_EVIDENCE_KIND
        or report.get('runNumber') != 95
        or report.get('frontierId') != 'G01'
        or report.get('scenarioId') is not None
        or report.get('epochId') != CODEX_TITLE_QUERY_RENDER_EPOCH_ID
        or report.get('profileId') != CODEX_TITLE_QUERY_RENDER_PROFILE_ID
        or report.get('profile') != 'codex-luna-max-anonymous-title-query-render-agent-mcp-v1'
        or report.get('model') != 'gpt-6-luna'
        or report.get('reasoningEffort') != 'max'
        or report.get('toolNames') != CODEX_TITLE_QUERY_RENDER_TOOL_NAMES
        or report.get('argumentProfile') != CODEX_TITLE_QUERY_RENDER_ARGUMENT_PROFILE
        or report.get('expectedArgumentsSha256') != CODEX_TITLE_QUERY_RENDER_EXPECTED_ARGUMENTS_SHA256
        or report.get('registrySha256') != CODEX_TITLE_QUERY_RENDER_PROFILE_REGISTRY_SHA256
        or report.get('networkMode') != CODEX_TITLE_QUERY_RENDER_NETWORK_MODE
        or report.get('resultStatus') != 'SUCCESS'
        or report.get('processExitCode') != 0
        or report.get('eventStreamParsed') is not True
        or report.get('turnCompleted') is not True
        or report.get('codexMcpToolEventCount') != 2
        or report.get('codexRunCount') != 1
        or report.get('codexErrorItemCount') != 0
        or report.get('nonMcpToolEventCount') != 0
        or report.get('nonMcpToolTypes') != []
        or report.get('shellToolCallCount') != 0
        or report.get('allowedCallCount') != 2
        or report.get('deniedCallCount') != 0
        or not codex_title_query_render_frontier_is_matrix_only()
        or type(pr_number) is not int
        or pr_number < 1
        or not codex_title_query_render_profile_revision_has_implementation(report.get('sourceRevision'))
        or not _codex_relations_report_matches_candidate_revision(
            path, report.get('sourceRevision'), CODEX_TITLE_QUERY_RENDER_REPORT_RELATIVE_PATH,
        )
    ):
        return False
    current_epoch_status = epoch_status or codex_title_query_render_profile_epoch_harness_status(pr_number)
    if not codex_title_query_render_profile_report_candidate_binding_is_current(report, current_epoch_status):
        return False
    status = harness_status or codex_title_query_render_profile_harness_status(pr_number)
    disposition = codex_title_query_render_profile_disposition_matches_report(
        report, status, report_sha256,
    )
    if disposition is None:
        return False
    validator = ROOT / 'scripts/acceptance/validate-title-query-render-agent-mcp-report.mjs'
    validation = subprocess.run(
        ['node', str(validator)],
        cwd=ROOT,
        input=json.dumps({
            'claim': disposition,
            'reportBytesBase64': base64.b64encode(report_bytes).decode('ascii'),
        }),
        capture_output=True,
        text=True,
        timeout=30,
        check=False,
    )
    if validation.returncode != 0:
        return False
    try:
        result = json.loads(validation.stdout)
    except (TypeError, ValueError):
        return False
    return result.get('passed') is True and result.get('reportSha256') == report_sha256


