def codex_p07_profile_disposition_matches_report(
    report: dict[str, object], harness_status: object, report_sha256: object,
) -> dict[str, object] | None:
    """Require the exact P07 report bytes to match its durable terminal Harness disposition."""
    if not isinstance(harness_status, dict):
        return None
    receipt = report.get('runnerReceipt')
    disposition = harness_status.get('disposition')
    if (
        harness_status.get('state') != 'REPORT_WRITTEN'
        or harness_status.get('profile_id') != CODEX_P07_PROFILE_ID
        or harness_status.get('pr') != report.get('prNumber')
        or harness_status.get('tool_name') != CODEX_P07_TOOL_NAME
        or harness_status.get('argument_profile') != CODEX_P07_ARGUMENT_PROFILE
        or harness_status.get('expected_arguments_sha256') != CODEX_P07_EXPECTED_ARGUMENTS_SHA256
        or harness_status.get('registry_sha256') != CODEX_P07_PROFILE_REGISTRY_SHA256
        or harness_status.get('claim_label_present') is not True
        or harness_status.get('terminal_label_present') is not True
        or not isinstance(disposition, dict)
        or not isinstance(receipt, dict)
        or not isinstance(report_sha256, str)
        or re.fullmatch(r'[0-9a-f]{64}', report_sha256) is None
    ):
        return None
    expected = {
        'claimId': report.get('claimId'),
        'profileId': CODEX_P07_PROFILE_ID,
        'frontierId': 'P07',
        'epochId': CODEX_P07_EPOCH_ID,
        'runNumber': 95,
        'prNumber': report.get('prNumber'),
        'state': 'REPORT_WRITTEN',
        'sourceCandidateSha': report.get('sourceRevision'),
        'baseSha': report.get('baseSha'),
        'ciSha': report.get('sourceRevision'),
        'ciStatus': 'SUCCESS',
        'reviewerId': report.get('reviewerId'),
        'bundleSha256': report.get('mcpBundleSha256'),
        'registrySha256': CODEX_P07_PROFILE_REGISTRY_SHA256,
        'toolName': CODEX_P07_TOOL_NAME,
        'argumentProfile': CODEX_P07_ARGUMENT_PROFILE,
        'expectedArgumentsSha256': CODEX_P07_EXPECTED_ARGUMENTS_SHA256,
        'reportWritten': True,
        'reportPath': CODEX_P07_REPORT_RELATIVE_PATH,
        'reportSha256': report_sha256,
        'retryAllowed': False,
        'runnerReceiptPublicKey': receipt.get('publicKeyBase64'),
        'runnerReceiptPublicKeySha256': receipt.get('publicKeySha256'),
        'runnerReceiptSha256': _canonical_json_sha256(receipt),
    }
    if any(disposition.get(key) != value for key, value in expected.items()):
        return None
    return disposition


def codex_p07_frontier_is_partial(require_report_ref: bool = False) -> bool:
    """Allow only partial P07 credit for the observed quarter sample, never full acceptance."""
    try:
        frontier = json.loads((ROOT / 'docs/product/frontier-ledger.json').read_text(encoding='utf-8'))
    except (OSError, ValueError):
        return False
    records = frontier.get('records') if isinstance(frontier, dict) else None
    record = next(
        (item for item in records or [] if isinstance(item, dict) and item.get('id') == 'P07'),
        None,
    )
    source_refs = record.get('source_refs') if isinstance(record, dict) else None
    return bool(
        isinstance(record, dict)
        and record.get('status') == 'PARTIAL'
        and isinstance(source_refs, list)
        and CODEX_P07_SELECTION_EVIDENCE_RELATIVE_PATH in source_refs
        and (not require_report_ref or CODEX_P07_REPORT_RELATIVE_PATH in source_refs)
    )


def codex_p07_profile_report_candidate_binding_is_current(
    report: dict[str, object], epoch_status: object,
) -> bool:
    candidate = None
    if isinstance(epoch_status, dict):
        epoch_result = epoch_status.get('epoch')
        epoch = epoch_result.get('state') if isinstance(epoch_result, dict) else None
        candidate = epoch.get('candidate_sha') if isinstance(epoch, dict) else None
    paths = _codex_p07_profile_report_candidate_paths(report.get('sourceRevision'), candidate)
    bundle_sha256 = codex_g26_candidate_bundle_sha256(candidate)
    return codex_p07_profile_candidate_binding_is_valid(
        report, epoch_status, paths, bundle_sha256,
    )


def codex_p07_profile_report_is_valid(
    report: object,
    harness_status: object = None,
    report_path: Path | None = None,
    epoch_status: object = None,
) -> bool:
    """Validate the signed P07 report while preserving its partial scenario scope."""
    if not isinstance(report, dict) or set(report) != CODEX_P07_REPORT_FIELDS:
        return False
    path = report_path or (LIVE_PROBE_DIR / Path(CODEX_P07_REPORT_RELATIVE_PATH).name)
    try:
        relative_path = path.resolve().relative_to(ROOT.resolve()).as_posix()
        report_bytes = path.read_bytes()
    except (OSError, ValueError):
        return False
    source_revision = report.get('sourceRevision')
    pr_number = report.get('prNumber')
    answer_checks = report.get('answerChecks')
    privacy = report.get('privacy')
    if (
        relative_path != CODEX_P07_REPORT_RELATIVE_PATH
        or len(report_bytes) > 64 * 1024
        or type(report.get('schemaVersion')) is not int
        or report.get('schemaVersion') != 1
        or report.get('evidenceKind') != CODEX_P07_EVIDENCE_KIND
        or type(report.get('runNumber')) is not int
        or report.get('runNumber') != 95
        or report.get('frontierId') != 'P07'
        or report.get('scenarioId') != 'P07'
        or report.get('epochId') != CODEX_P07_EPOCH_ID
        or report.get('profileId') != CODEX_P07_PROFILE_ID
        or report.get('profile') != 'codex-luna-max-agent-mcp-profile-v1'
        or report.get('model') != 'gpt-6-luna'
        or report.get('reasoningEffort') != 'max'
        or not isinstance(report.get('reviewerId'), str)
        or re.fullmatch(rf'gpt-6-luna-max-run95-pr{pr_number}-round[1-9]\d*', report['reviewerId']) is None
        or not isinstance(report.get('codexCliVersion'), str)
        or re.fullmatch(r'\d+\.\d+\.\d+', report['codexCliVersion']) is None
        or report.get('toolName') != CODEX_P07_TOOL_NAME
        or report.get('argumentProfile') != CODEX_P07_ARGUMENT_PROFILE
        or report.get('expectedArgumentsSha256') != CODEX_P07_EXPECTED_ARGUMENTS_SHA256
        or report.get('registrySha256') != CODEX_P07_PROFILE_REGISTRY_SHA256
        or not isinstance(source_revision, str)
        or re.fullmatch(r'[0-9a-f]{40}', source_revision) is None
        or not codex_p07_profile_revision_has_implementation(source_revision)
        or not codex_p07_frontier_is_partial(require_report_ref=True)
        or not isinstance(report.get('baseSha'), str)
        or re.fullmatch(r'[0-9a-f]{40}', report['baseSha']) is None
        or _run_repository_git(ROOT, 'merge-base', '--is-ancestor', report['baseSha'], source_revision).returncode != 0
        or report.get('ciSha') != source_revision
        or report.get('ciStatus') != 'SUCCESS'
        or type(pr_number) is not int
        or pr_number < 1
        or not isinstance(report.get('claimId'), str)
        or re.fullmatch(rf'profile-run-95-pr-{pr_number}-{source_revision[:12]}-\d+', report['claimId']) is None
        or report.get('mcpBundleSha256') != codex_g26_candidate_bundle_sha256(source_revision)
        or report.get('resultStatus') != 'SUCCESS'
        or type(report.get('processExitCode')) is not int
        or report.get('processExitCode') != 0
        or report.get('mcpTextProjectionValid') is not True
        or report.get('eventStreamParsed') is not True
        or report.get('turnCompleted') is not True
        or type(report.get('codexMcpToolEventCount')) is not int
        or report.get('codexMcpToolEventCount') != 1
        or type(report.get('codexErrorItemCount')) is not int
        or report.get('codexErrorItemCount') != 0
        or type(report.get('nonMcpToolEventCount')) is not int
        or report.get('nonMcpToolEventCount') != 0
        or report.get('nonMcpToolTypes') != []
        or type(report.get('shellToolCallCount')) is not int
        or report.get('shellToolCallCount') != 0
        or type(report.get('allowedCallCount')) is not int
        or report.get('allowedCallCount') != 1
        or type(report.get('deniedCallCount')) is not int
        or report.get('deniedCallCount') != 0
        or report.get('serverToolNames') != [CODEX_P07_TOOL_NAME]
        or type(report.get('serverToolCount')) is not int
        or report.get('serverToolCount') != 1
        or report.get('mcpServerNames') != ['bgk_p07_person_season']
        or report.get('answerCheckMethod') != CODEX_P07_ANSWER_CHECK_METHOD
        or not isinstance(report.get('answerSha256'), str)
        or re.fullmatch(r'[0-9a-f]{64}', report['answerSha256']) is None
        or type(report.get('answerUtf8Bytes')) is not int
        or not 0 < report['answerUtf8Bytes'] <= CODEX_P07_PROFILE['maxAnswerBytes']
        or not isinstance(answer_checks, dict)
        or set(answer_checks) != CODEX_P07_ANSWER_CHECK_FIELDS
        or any(value is not True for value in answer_checks.values())
        or not isinstance(privacy, dict)
        or set(privacy) != CODEX_P07_PRIVACY_FIELDS
        or any(value is not False for value in privacy.values())
        or _contains_forbidden_codex_content(report)
    ):
        return False

    try:
        catalog_bytes = CATALOG.read_bytes()
        catalog = json.loads(catalog_bytes)
        catalog_tool = next(
            (item for item in catalog if isinstance(item, dict) and item.get('name') == CODEX_P07_TOOL_NAME),
            None,
        )
    except (OSError, ValueError):
        return False
    if (
        not isinstance(catalog_tool, dict)
        or catalog_tool.get('auth') != 'none'
        or catalog_tool.get('risk') != 'read'
        or report.get('catalogSha256') != hashlib.sha256(catalog_bytes).hexdigest()
        or report.get('toolDescriptionSha256') != hashlib.sha256(catalog_tool.get('description', '').encode('utf-8')).hexdigest()
        or report.get('inputSchemaSha256') != _canonical_json_sha256(catalog_tool.get('inputSchema'))
    ):
        return False

    report_sha256 = hashlib.sha256(report_bytes).hexdigest()
    current_epoch_status = epoch_status or codex_p07_profile_epoch_harness_status(pr_number)
    if not codex_p07_profile_report_candidate_binding_is_current(report, current_epoch_status):
        return False
    status = harness_status or codex_p07_profile_harness_status(pr_number)
    disposition = codex_p07_profile_disposition_matches_report(report, status, report_sha256)
    if disposition is None:
        return False
    validation = subprocess.run(
        ['node', str(ROOT / 'scripts/acceptance/validate-p07-person-season-report.mjs')],
        cwd=ROOT,
        input=json.dumps({
            'claim': disposition,
            'reportBytesBase64': base64.b64encode(report_bytes).decode('ascii'),
        }),
        capture_output=True,
        text=True,
        timeout=30,
        check=False,
    )
    if validation.returncode != 0:
        return False
    try:
        result = json.loads(validation.stdout)
    except (TypeError, ValueError):
        return False
    return result.get('passed') is True and result.get('reportSha256') == report_sha256



